package org.casbin.jcasbin.log;

import org.junit.jupiter.api.Test;

import java.io.ByteArrayOutputStream;
import java.io.PrintStream;
import java.lang.reflect.Field;
import java.util.Arrays;
import java.util.HashMap;
import java.util.Map;

import static org.junit.jupiter.api.Assertions.*;

public class LogPolicyTests {

    private void setEnabledViaReflection(DefaultLogger logger, boolean value) {
        Class<?> clazz = DefaultLogger.class;
        try {
            Field f = clazz.getDeclaredField("enabled");
            f.setAccessible(true);
            f.setBoolean(logger, value);
            return;
        } catch (Exception e) {
            // try alternative name
            try {
                Field f = clazz.getDeclaredField("isEnabled");
                f.setAccessible(true);
                f.setBoolean(logger, value);
                return;
            } catch (Exception ex) {
                throw new RuntimeException(ex);
            }
        }
    }

    private boolean getEnabledViaReflection(DefaultLogger logger) {
        Class<?> clazz = DefaultLogger.class;
        try {
            Field f = clazz.getDeclaredField("enabled");
            f.setAccessible(true);
            return f.getBoolean(logger);
        } catch (Exception e) {
            try {
                Field f = clazz.getDeclaredField("isEnabled");
                f.setAccessible(true);
                return f.getBoolean(logger);
            } catch (Exception ex) {
                throw new RuntimeException(ex);
            }
        }
    }

    @Test
    public void testLogPolicy_PrintsWhenEnabled() {
        Map<String, String[][]> policy = new HashMap<>();
        String[][] rows = new String[][] {
                {"alice", "data1"},
                {"bob", "data2"}
        };
        policy.put("p", rows);

        DefaultLogger logger = new DefaultLogger();
        setEnabledViaReflection(logger, true);

        ByteArrayOutputStream outContent = new ByteArrayOutputStream();
        PrintStream originalOut = System.out;
        System.setOut(new PrintStream(outContent));

        try {
            logger.logPolicy(policy);
        } finally {
            System.out.flush();
            System.setOut(originalOut);
        }

        String output = outContent.toString();
        assertTrue(output.contains("alice"), "Output should contain policy value 'alice'");
        assertTrue(output.contains("data1"), "Output should contain policy value 'data1'");
        assertTrue(output.contains("bob"), "Output should contain policy value 'bob'");
        assertTrue(output.contains("data2"), "Output should contain policy value 'data2'");
    }

    @Test
    public void testLogPolicy_NoOutputWhenDisabled() {
        Map<String, String[][]> policy = new HashMap<>();
        String[][] rows = new String[][] {
                {"alice", "data1"},
                {"bob", "data2"}
        };
        policy.put("p", rows);

        DefaultLogger logger = new DefaultLogger();
        // Do not enable logging; rely on default state

        ByteArrayOutputStream outContent = new ByteArrayOutputStream();
        PrintStream originalOut = System.out;
        System.setOut(new PrintStream(outContent));

        try {
            logger.logPolicy(policy);
        } finally {
            System.out.flush();
            System.setOut(originalOut);
        }

        String output = outContent.toString();
        assertTrue(output.isEmpty() || output.trim().isEmpty(), "No output should be produced when logging is disabled");
    }

    @Test
    public void testLogPolicy_InputUnchanged() {
        Map<String, String[][]> policy = new HashMap<>();
        policy.put("p", new String[][]{
                {"alice", "data1"},
                {"bob", "data2"}
        });

        // Deep copy of policy for later comparison
        Map<String, String[][]> snapshot = new HashMap<>();
        for (Map.Entry<String, String[][]> e : policy.entrySet()) {
            String[][] val = e.getValue();
            String[][] copy = new String[val.length][];
            for (int i = 0; i < val.length; i++) {
                copy[i] = val[i].clone();
            }
            snapshot.put(e.getKey(), copy);
        }

        DefaultLogger logger = new DefaultLogger();
        setEnabledViaReflection(logger, true);

        logger.logPolicy(policy);

        for (String key : snapshot.keySet()) {
            String[][] beforeVal = snapshot.get(key);
            String[][] afterVal = policy.get(key);
            assertTrue(Arrays.deepEquals(beforeVal, afterVal),
                    "Policy map should remain unchanged after logPolicy call");
        }
    }

    @Test
    public void testLogPolicy_LoggerStateUnchanged() {
        Map<String, String[][]> policy = new HashMap<>();
        policy.put("p", new String[][]{
                {"alice", "data1"},
                {"bob", "data2"}
        });

        DefaultLogger logger = new DefaultLogger();
        setEnabledViaReflection(logger, true);
        boolean before = getEnabledViaReflection(logger);

        logger.logPolicy(policy);

        boolean after = getEnabledViaReflection(logger);
        assertEquals(before, after, "Logger enabled state should remain unchanged after logPolicy");
    }
}

