import java.io.PrintStream;
import java.lang.reflect.Constructor;
import java.lang.reflect.Method;
import java.lang.reflect.InvocationTargetException;

public class LogModelTests {

    private final PrintStream originalOut = System.out;
    private ByteArrayOutputStream outContent;

    @BeforeEach
    public void setUp() {
        outContent = new ByteArrayOutputStream();
        System.setOut(new PrintStream(outContent));
    }

    @AfterEach
    public void tearDown() {
        System.setOut(originalOut);
    }

    private Object createLogger(boolean enabled) throws Exception {
        Class<?> cls = Class.forName("org.casbin.jcasbin.log.DefaultLogger");
        try {
            Constructor<?> c = cls.getDeclaredConstructor(boolean.class);
            c.setAccessible(true);
            return c.newInstance(enabled);
        } catch (NoSuchMethodException e) {
            // Fallback to no-arg constructor if boolean constructor doesn't exist
            Constructor<?> c = cls.getDeclaredConstructor();
            c.setAccessible(true);
            Object instance = c.newInstance();
            try {
                Method setter = cls.getMethod("setEnabled", boolean.class);
                setter.invoke(instance, enabled);
            } catch (NoSuchMethodException ignore) {
            }
            return instance;
        }
    }

    private String[][] sampleModel() {
        return new String[][] { {"a","b"}, {"c"} };
    }

    @Test
    public void testLogModel_enabledPrintsFormattedModel() throws Exception {
        Object logger = createLogger(true);
        Method m = logger.getClass().getMethod("logModel", String[][].class);
        String[][] model = sampleModel();
        m.invoke(logger, (Object) model);

        String normalizedOut = outContent.toString().replace("\r\n", "\n").replace("\r", "\n");
        String[] lines = normalizedOut.split("\n");
        // Remove potential trailing empty line
        if (lines.length > 0 && lines[lines.length - 1].isEmpty()) {
            String[] trimmed = new String[lines.length - 1];
            System.arraycopy(lines, 0, trimmed, 0, lines.length - 1);
            lines = trimmed;
        }

        assertEquals(2, lines.length);
        assertEquals("Model: a, b", lines[0]);
        assertEquals("c", lines[1]);
    }

    @Test
    public void testLogModel_disabledNoOutput() throws Exception {
        Object logger = createLogger(false);
        Method m = logger.getClass().getMethod("logModel", String[][].class);
        String[][] model = sampleModel();
        m.invoke(logger, (Object) model);

        assertEquals("", outContent.toString());
    }

    @Test
