public class PrintModelTests {

    @Test
    public void testPrintModelWithEmptyModelDoesNotThrow() throws Exception {
        Model m = new Model();
        Field modelField = Model.class.getDeclaredField("model");
        modelField.setAccessible(true);
        modelField.set(m, new HashMap<>());

        // Should not throw any exceptions
        m.printModel();

        @SuppressWarnings("unchecked")
        Map<?, ?> current = (Map<?, ?>) modelField.get(m);
        assertNotNull(current, "Model map should not be null");
        assertTrue(current.isEmpty(), "Model map should be empty after initialization");
    }

    @Test
    public void testPrintModelWithDataDoesNotModifyModel() throws Exception {
        Model m = new Model();
        Field modelField = Model.class.getDeclaredField("model");
        modelField.setAccessible(true);

        // Build a nested map structure to simulate the model content
        Map data = new HashMap();
        Map inner = new HashMap();
        List<String> lst = new ArrayList<>();
        lst.add("assert1");
        inner.put("a", lst);
        data.put("r", inner);

        // Inject the data into the model
        modelField.set(m, data);

        // Create a deep copy of the data to compare after printModel
        Map copy = deepCopy(data);

        m.printModel();

        @SuppressWarnings("unchecked")
        Map current = (Map) modelField.get(m);

        // Verify that the content has not been mutated by printModel
        assertEquals(copy, current, "Model content should remain unchanged after printModel.");
    }

    @SuppressWarnings("unchecked")
    private Map deepCopy(Map original) {
        Map copied = new HashMap();
        for (Object e : original.entrySet()) {
            Map.Entry entry = (Map.Entry) e;
            Object key = entry.getKey();
            Object value = entry.getValue();

            if (value instanceof Map) {
                Map inner = (Map) value;
                Map innerCopy = new HashMap();
                for (Object i : inner.entrySet()) {
                    Map.Entry innerEntry = (Map.Entry) i;
                    Object innerKey = innerEntry.getKey();
                    Object innerValue = innerEntry.getValue();

                    if (innerValue instanceof List) {
                        List innerList = (List) innerValue;
                        List innerListCopy = new ArrayList(innerList);
                        innerCopy.put(innerKey, innerListCopy);
                    } else {
                        innerCopy.put(innerKey, innerValue);
                    }
                }
                copied.put(key, innerCopy);
            } else if (value instanceof List) {
                copied.put(key, new ArrayList((List) value));
            } else {
                copied.put(key, value);
            }
        }
        return copied;
    }
}

