import org.casbin.jcasbin.RoleManager;
import org.junit.jupiter.api.Test;

import java.lang.reflect.InvocationHandler;
import java.lang.reflect.Method;
import java.lang.reflect.Proxy;
import java.util.*;

import static org.junit.jupiter.api.Assertions.*;

public class CheckTests {

    private static RoleManager createRoleManagerProxy() {
        InvocationHandler handler = new InvocationHandler() {
            private final Map<String, List<String>> graph = new HashMap<>();

            @Override
            public Object invoke(Object proxy, Method method, Object[] args) throws Throwable {
                String name = method.getName();

                if ("getRoles".equals(name)) {
                    return graph;
                } else if ("addLink".equals(name)) {
                    String a = (String) args[0];
                    String b = (String) args[1];
                    graph.computeIfAbsent(a, k -> new ArrayList<>()).add(b);
                    return null;
                } else if ("clear".equals(name)) {
                    graph.clear();
                    return null;
                } else if ("hasLink".equals(name)) {
                    String a = (String) args[0];
                    String b = (String) args[1];
                    List<String> adj = graph.get(a);
                    return adj != null && adj.contains(b);
                } else if ("size".equals(name)) {
                    return graph.size();
                }

                throw new UnsupportedOperationException("Unsupported method: " + name);
            }
        };

        return (RoleManager) Proxy.newProxyInstance(
                RoleManager.class.getClassLoader(),
                new Class[]{RoleManager.class},
                handler
        );
    }

    @Test
    public void testCheckNoCycle() {
        RoleManager rm = createRoleManagerProxy();
        rm.addLink("A", "B", 0);
        rm.addLink("B", "C", 0);

        DefaultDetector detector = new DefaultDetector();
        String result = detector.check(rm);

        assertNull(result, "Expected no cycle in the graph");
    }

    @Test
    public void testCheckCycleReturnsNodeAndIsIdempotent() {
        RoleManager rm = createRoleManagerProxy();
        rm.addLink("A", "B", 0);
        rm.addLink("B", "C", 0);
        rm.addLink("C", "A", 0); // creates a cycle A -> B -> C -> A

        DefaultDetector detector = new DefaultDetector();
        String firstResult = detector.check(rm);
        assertNotNull(firstResult, "Expected a node from the cycle to be returned");
        assertTrue(Arrays.asList("A", "B", "C").contains(firstResult),
                "Returned node should be one of the cycle nodes");

        // Idempotence: running again should give the same result
        String secondResult = detector.check(rm);
        assertEquals(firstResult, secondResult, "check should be idempotent for the same RoleManager");
    }
}

